import numpy as np

def cost_optimal_threshold(y_true, y_proba, cost_fp=10, cost_fn=1000):
    y_true = np.asarray(y_true)
    y_proba = np.asarray(y_proba)
    best_th, best_cost = 0.5, float("inf")
    for th in np.arange(0.01, 1.0, 0.01):
        pred = (y_proba >= th).astype(int)
        fp = int(((pred == 1) & (y_true == 0)).sum())
        fn = int(((pred == 0) & (y_true == 1)).sum())
        cost = fp * cost_fp + fn * cost_fn
        if cost < best_cost:
            best_cost, best_th = cost, th
    return round(float(best_th), 4)
